import type { LevelRange, Tile } from "@stallion/geometry";
import { decode, encode, type StallionObject } from "@stallion/schema";
import { type DBSchema, type IDBPDatabase, type IDBPObjectStore, openDB } from "idb";

export type StoredObject = { tile: Tile; object: StallionObject };

type TileRecord = {
  boardId: string;
  level: number;
  tx: number;
  ty: number;
  objectId: string;
  bytes: Uint8Array;
};

type TileKey = [string, number, number, number, string];

interface StallionDB extends DBSchema {
  objects: { key: TileKey; value: TileRecord };
}

type ObjectStore = IDBPObjectStore<StallionDB, ["objects"], "objects", "readonly">;

const DB_NAME = "stallion";
const DB_VERSION = 1;

const openStallionDB = (): Promise<IDBPDatabase<StallionDB>> =>
  openDB<StallionDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      db.createObjectStore("objects", { keyPath: ["boardId", "level", "tx", "ty", "objectId"] });
    },
  });

export type BoardStore = {
  put(stored: StoredObject): Promise<void>;
  query(ranges: readonly LevelRange[]): Promise<StoredObject[]>;
  close(): void;
};

export async function openBoardStore(boardId: string): Promise<BoardStore> {
  const db = await openStallionDB();

  const put = async ({ tile, object }: StoredObject): Promise<void> => {
    await db.put("objects", {
      boardId,
      level: tile.level,
      tx: tile.tx,
      ty: tile.ty,
      objectId: object.objectId,
      bytes: encode(object),
    });
  };

  const queryLevel = async (store: ObjectStore, range: LevelRange): Promise<StoredObject[]> => {
    const keys = IDBKeyRange.bound(
      [boardId, range.level, range.minTx],
      [boardId, range.level, range.maxTx, []],
    );
    const records = await store.getAll(keys);
    return records.flatMap((record) => {
      if (record.ty < range.minTy || record.ty > range.maxTy) return [];
      const decoded = decode(record.bytes);
      if (!decoded.ok) {
        throw new TypeError(`Stored object ${record.objectId} is invalid: ${decoded.error}`);
      }
      return [
        { tile: { level: record.level, tx: record.tx, ty: record.ty }, object: decoded.value },
      ];
    });
  };

  const query = async (ranges: readonly LevelRange[]): Promise<StoredObject[]> => {
    const tx = db.transaction("objects", "readonly");
    const results = await Promise.all(ranges.map((range) => queryLevel(tx.store, range)));
    await tx.done;
    return results.flat();
  };

  return { put, query, close: () => db.close() };
}
import { useEffect, useRef, useState } from "preact/hooks";
import { createSurface, type Tool } from "./surface";
import { Toolbar } from "./toolbar";

const ISSUE_URL = "https://github.com/mvhenten/stallion/issues/new";

const reportLink = (message: string): string =>
  `${ISSUE_URL}?${new URLSearchParams({
    title: "Drawing board error",
    body: `${message}\n\nBrowser: ${navigator.userAgent}`,
  })}`;

export function Board({ boardId }: { boardId: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [tool, setTool] = useState<Tool>({
    size: "Medium",
    primary: 0,
    secondary: 4,
    pan: false,
  });
  const [error, setError] = useState<string | undefined>(undefined);
  const toolRef = useRef(tool);
  toolRef.current = tool;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const surface = createSurface(canvas, boardId, () => toolRef.current, setError);
    return () => surface.dispose();
  }, [boardId]);

  return (
    <main class="board">
      <canvas
        ref={canvasRef}
        class={tool.pan ? "surface panning" : "surface"}
        aria-label={`Drawing board ${boardId}`}
      />
      <Toolbar tool={tool} onChange={setTool} />
      {error && (
        <div class="error" role="alert">
          <p>{error}. Strokes may not be saved; reload to try again.</p>
          <a href={reportLink(error)} target="_blank" rel="noreferrer">
            Report an issue
          </a>
        </div>
      )}
    </main>
  );
}
import { PALETTE, PENCIL_SIZES } from "./stroke";
import type { Tool } from "./surface";

const DOT_PX = { Small: 4, Medium: 9, Large: 16 } as const;

type ToolbarProps = { tool: Tool; onChange: (tool: Tool) => void };

export function Toolbar({ tool, onChange }: ToolbarProps) {
  return (
    <div class="toolbar" role="toolbar" aria-label="Drawing tools">
      <fieldset class="group" aria-label="Pencil size">
        {PENCIL_SIZES.map((size) => (
          <button
            key={size}
            type="button"
            aria-pressed={tool.size === size}
            aria-label={`${size} pencil`}
            class="tool"
            onClick={() => onChange({ ...tool, size, pan: false })}
          >
            <span class="dot" style={{ width: DOT_PX[size], height: DOT_PX[size] }} />
          </button>
        ))}
      </fieldset>
      <fieldset class="group" aria-label="Colour">
        {PALETTE.map((colour, index) => (
          <button
            key={colour}
            type="button"
            aria-pressed={tool.primary === index}
            aria-label={`Colour ${index + 1}`}
            title="Tap for primary, right-click or long-press for secondary"
            class={tool.secondary === index ? "tool swatch secondary" : "tool swatch"}
            style={{ background: colour }}
            onClick={() => onChange({ ...tool, primary: index })}
            onContextMenu={(event) => {
              event.preventDefault();
              onChange({ ...tool, secondary: index });
            }}
          />
        ))}
      </fieldset>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.pan}
        aria-label="Pan tool"
        title="Drag with one finger to move the board"
        onClick={() => onChange({ ...tool, pan: !tool.pan })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M12 2v20M2 12h20M12 2l-3 3M12 2l3 3M12 22l-3-3M12 22l3-3M2 12l3-3M2 12l3 3M22 12l-3-3M22 12l-3 3"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool pair"
        aria-label="Swap primary and secondary colour"
        onClick={() => onChange({ ...tool, primary: tool.secondary, secondary: tool.primary })}
      >
        <span class="chip back" style={{ background: PALETTE[tool.secondary] }} />
        <span class="chip front" style={{ background: PALETTE[tool.primary] }} />
      </button>
    </div>
  );
}
import type { StoredObject } from "@stallion/client-store";
import {
  type BBox,
  nativeLevel,
  type Point,
  place,
  TILE_SIZE,
  type Tile,
  tileWorldSize,
  toTileLocal,
} from "@stallion/geometry";
import type { PencilSize, Stroke, Point as StrokePoint } from "@stallion/schema";
import getStroke, { type StrokeOptions } from "perfect-freehand";

export const PALETTE = ["#1f2328", "#e5484d", "#f76b15", "#30a46c", "#0090ff", "#8e4ec6"] as const;

export const PENCIL_SIZES: readonly PencilSize[] = ["Small", "Medium", "Large"];

const PENCIL_PX: Record<PencilSize, number> = { Small: 3, Medium: 8, Large: 20 };

export const MAX_POINTS = 4096;

export const strokeWorldWidth = (size: PencilSize, nativeZoom: number): number =>
  PENCIL_PX[size] * 2 ** (nativeZoom - 0.5);

const strokeOptions = (size: number, last: boolean): StrokeOptions => ({
  size,
  thinning: 0.5,
  smoothing: 0.5,
  streamline: 0.4,
  simulatePressure: false,
  last,
});

export const outlinePath = (
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): Path2D => {
  const outline = getStroke([...points], strokeOptions(size, last));
  const path = new Path2D();
  const [first, ...rest] = outline;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  path.closePath();
  return path;
};

export type Draft = {
  colour: number;
  size: PencilSize;
  nativeZoom: number;
  points: StrokePoint[];
};

export const startDraft = (colour: number, size: PencilSize, zoom: number): Draft => ({
  colour,
  size,
  nativeZoom: nativeLevel(zoom),
  points: [],
});

const draftBounds = (draft: Draft): BBox => {
  const margin = strokeWorldWidth(draft.size, draft.nativeZoom);
  const xs = draft.points.map((p) => p[0]);
  const ys = draft.points.map((p) => p[1]);
  return {
    minX: Math.min(...xs) - margin,
    minY: Math.min(...ys) - margin,
    maxX: Math.max(...xs) + margin,
    maxY: Math.max(...ys) + margin,
  };
};

const randomHex = (bytes: number): string =>
  Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");

const newObjectId = (): string => `${Date.now().toString(36).padStart(9, "0")}${randomHex(6)}`;

export const finishDraft = (draft: Draft): StoredObject | undefined => {
  if (draft.points.length === 0) return undefined;
  const bbox = draftBounds(draft);
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const { tile } = placed;
  const stroke: Stroke = {
    type: "Stroke",
    objectId: newObjectId(),
    nativeZoom: draft.nativeZoom,
    bbox,
    colour: draft.colour,
    size: draft.size,
    points: draft.points.map(([x, y, pressure]) => {
      const local = toTileLocal(tile, { x, y });
      return [local.x, local.y, pressure];
    }),
  };
  return { tile, object: stroke };
};

export const localScale = (tile: Tile): number => tileWorldSize(tile.level) / TILE_SIZE;

export const strokeLocalPath = (tile: Tile, stroke: Stroke): Path2D =>
  outlinePath(
    stroke.points,
    strokeWorldWidth(stroke.size, stroke.nativeZoom) / localScale(tile),
    true,
  );

export const draftScreenPath = (
  draft: Draft,
  toScreen: (world: Point) => Point,
  zoom: number,
): Path2D =>
  outlinePath(
    draft.points.map(([x, y, pressure]) => {
      const screen = toScreen({ x, y });
      return [screen.x, screen.y, pressure];
    }),
    strokeWorldWidth(draft.size, draft.nativeZoom) * zoom,
    false,
  );
import type { Point } from "@stallion/geometry";

export type PointerKind = "mouse" | "pen" | "touch";

export type PointerDown = {
  pointerId: number;
  kind: PointerKind;
  button: number;
  point: Point;
};

export type Modifiers = { panTool: boolean; spaceDown: boolean };

export type Effect =
  | { type: "StartStroke"; secondary: boolean }
  | { type: "ExtendStroke" }
  | { type: "CommitStroke" }
  | { type: "DiscardStroke" }
  | { type: "Pan"; dx: number; dy: number }
  | { type: "Pinch"; from: readonly [Point, Point]; to: readonly [Point, Point] };

type Tracked = { point: Point; kind: PointerKind };

type State =
  | { mode: "Idle" }
  | { mode: "Draw"; pointerId: number }
  | { mode: "Pan"; pointerId: number }
  | { mode: "Pinch" };

export type Gestures = {
  down(event: PointerDown, modifiers: Modifiers): Effect[];
  move(pointerId: number, point: Point): Effect[];
  up(pointerId: number): Effect[];
  cancel(pointerId: number): Effect[];
};

const PRIMARY = 0;
const MIDDLE = 1;
const SECONDARY = 2;

export function createGestures(): Gestures {
  const pointers = new Map<number, Tracked>();
  let state: State = { mode: "Idle" };
  let penSeen = false;

  const touchIds = (): number[] =>
    [...pointers.entries()].filter(([, tracked]) => tracked.kind === "touch").map(([id]) => id);

  const wantsPan = (event: PointerDown, modifiers: Modifiers): boolean => {
    if (event.button === MIDDLE) return true;
    if (event.button !== PRIMARY) return false;
    if (modifiers.panTool || modifiers.spaceDown) return true;
    return event.kind === "touch" && penSeen;
  };

  const down = (event: PointerDown, modifiers: Modifiers): Effect[] => {
    pointers.set(event.pointerId, { point: event.point, kind: event.kind });
    if (event.kind === "pen") penSeen = true;

    if (event.kind === "touch" && touchIds().length >= 2) {
      const discard = state.mode === "Draw" && pointers.get(state.pointerId)?.kind === "touch";
      if (state.mode === "Draw" && !discard) return [];
      state = { mode: "Pinch" };
      return discard ? [{ type: "DiscardStroke" }] : [];
    }

    if (state.mode !== "Idle") return [];
    if (wantsPan(event, modifiers)) {
      state = { mode: "Pan", pointerId: event.pointerId };
      return [];
    }
    if (event.button !== PRIMARY && event.button !== SECONDARY) return [];
    state = { mode: "Draw", pointerId: event.pointerId };
    return [{ type: "StartStroke", secondary: event.button === SECONDARY }];
  };

  const pinchEffect = (pointerId: number, point: Point): Effect[] => {
    const [first, second] = touchIds();
    if (first === undefined) return [];
    if (second === undefined) {
      const previous = pointers.get(first)?.point;
      if (first !== pointerId || !previous) return [];
      return [{ type: "Pan", dx: point.x - previous.x, dy: point.y - previous.y }];
    }
    if (pointerId !== first && pointerId !== second) return [];
    const a = pointers.get(first)?.point;
    const b = pointers.get(second)?.point;
    if (!a || !b) return [];
    const from = [a, b] as const;
    const to = pointerId === first ? ([point, b] as const) : ([a, point] as const);
    return [{ type: "Pinch", from, to }];
  };

  const move = (pointerId: number, point: Point): Effect[] => {
    const tracked = pointers.get(pointerId);
    if (!tracked) return [];
    const effects: Effect[] = [];
    if (state.mode === "Draw" && state.pointerId === pointerId) {
      effects.push({ type: "ExtendStroke" });
    }
    if (state.mode === "Pan" && state.pointerId === pointerId) {
      effects.push({ type: "Pan", dx: point.x - tracked.point.x, dy: point.y - tracked.point.y });
    }
    if (state.mode === "Pinch") effects.push(...pinchEffect(pointerId, point));
    pointers.set(pointerId, { ...tracked, point });
    return effects;
  };

  const end = (pointerId: number, cancelled: boolean): Effect[] => {
    if (!pointers.delete(pointerId)) return [];
    const effects: Effect[] = [];
    if (state.mode === "Draw" && state.pointerId === pointerId) {
      effects.push({ type: cancelled ? "DiscardStroke" : "CommitStroke" });
      state = touchIds().length > 0 ? { mode: "Pinch" } : { mode: "Idle" };
    }
    if (state.mode === "Pan" && state.pointerId === pointerId) state = { mode: "Idle" };
    if (state.mode === "Pinch" && touchIds().length === 0) state = { mode: "Idle" };
    if (pointers.size === 0) state = { mode: "Idle" };
    return effects;
  };

  return {
    down,
    move,
    up: (pointerId) => end(pointerId, false),
    cancel: (pointerId) => end(pointerId, true),
  };
}
