import { chromium } from "/home/mvhenten/development/reader/node_modules/playwright-core/index.mjs";
const dir = "/home/mvhenten/development/.tmp/stallion-eraser";
const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome", headless: true });
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));
const inked = () => page.evaluate(() => {
  const c = document.querySelector("canvas.surface");
  const d = c.getContext("2d").getImageData(0, 0, c.width, c.height).data;
  let n = 0; for (let i = 3; i < d.length; i += 4) if (d[i] > 0) n++; return n;
});
const rows = () => page.evaluate(() => new Promise((res, rej) => {
  const r = indexedDB.open("stallion"); r.onerror = rej;
  r.onsuccess = () => { const q = r.result.transaction("objects").objectStore("objects").count(); q.onsuccess = () => { res(q.result); r.result.close(); }; };
}));
await page.goto("http://100.104.44.51:5173/b/default", { waitUntil: "networkidle" });
await page.waitForTimeout(800);
const before = { ink: await inked(), rows: await rows() };
await page.mouse.move(300, 400); await page.mouse.down();
for (let x = 300; x <= 700; x += 10) await page.mouse.move(x, 400 + Math.sin(x / 40) * 30);
await page.mouse.up(); await page.waitForTimeout(500);
const drawn = { ink: await inked(), rows: await rows() };
await page.screenshot({ path: `${dir}/1-drawn.png` });
await page.getByRole("button", { name: "Eraser" }).click();
const pressed = await page.getByRole("button", { name: "Eraser" }).getAttribute("aria-pressed");
await page.mouse.move(500, 300); await page.mouse.down();
for (let y = 300; y <= 500; y += 15) await page.mouse.move(500, y);
await page.mouse.up(); await page.waitForTimeout(500);
const erased = { ink: await inked(), rows: await rows() };
await page.screenshot({ path: `${dir}/2-erased.png` });
await page.reload({ waitUntil: "networkidle" }); await page.waitForTimeout(1000);
const reloaded = { ink: await inked(), rows: await rows() };
await page.screenshot({ path: `${dir}/3-reloaded.png` });
console.log(JSON.stringify({ before, drawn, pressed, erased, reloaded, errors }, null, 1));
await browser.close();
EOF
cd ~/development/.tmp/stallion-eraser && timeout 120 node check.mjs

